use vstd::prelude::*;

verus! {
    fn frombuffer(buffer: &Vec<u8>, count: usize, offset: usize) -> Vec<u8>
        requires
            offset < buffer.len(),
            count <= buffer.len() - offset,
    ensures
        result.len() == count,
        forall|i: usize| 0 <= i < count ==> result[i] == buffer[offset + i],
    {
        let mut result: Vec<u8> = Vec::new();
        result.resize(count, 0); // Initialize the result vector with zeros

        let mut i: usize = 0;
        while i < count
            invariant
                0 <= i <= count,
                result.len() == count,
                forall|j: usize| 0 <= j < i ==> result[j] == buffer[offset + j],
            decreases count - i,
        {
            result[i] = buffer[offset + i]; // Copy the element from buffer to result
            i = i + 1; // Increment the index
        }

        result // Return the result vector
    }
}
